def md(df,fmt=None):
    df=df.copy(); cols=list(df.columns); s="| "+" | ".join(map(str,cols))+" |\n|"+"|".join(["---"]*len(cols))+"|\n"
    for _,r in df.iterrows():
        vals=[]
        for c in cols:
            v=r[c]
            if isinstance(v,float): v="" if np.isnan(v) else (f"{v:.2f}" if abs(v)<10 else f"{v:.1f}")
            vals.append(str(v).replace("|","\\|").replace("\n"," "))
        s+="| "+" | ".join(vals)+" |\n"
    return s
